package de.corporate.lc.check.service;
import de.corporate.lc.check.api.*;import de.corporate.lc.lc.repository.LetterOfCreditRepository;import org.apache.pdfbox.pdmodel.*;import org.apache.pdfbox.pdmodel.common.PDRectangle;import org.apache.pdfbox.pdmodel.font.*;import org.springframework.stereotype.Service;import java.io.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class DocumentCheckReportService{
 private final DocumentCheckService checks;private final LetterOfCreditRepository lcs;public DocumentCheckReportService(DocumentCheckService c,LetterOfCreditRepository l){checks=c;lcs=l;}
public Report create(UUID lcId)throws IOException{var lc=lcs.findById(lcId).orElseThrow();ReviewSummary review=checks.check(lcId);try(PDDocument pdf=new PDDocument();ByteArrayOutputStream out=new ByteArrayOutputStream()){var regular=new PDType1Font(Standard14Fonts.FontName.HELVETICA);var bold=new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD);PageWriter writer=new PageWriter(pdf,regular,bold);writer.title("LC DOCUMENT REVIEW REPORT");writer.field("LC reference",lc.getReference());writer.field("Generated",ZonedDateTime.now().format(DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm z")));writer.field("Overall status",review.status());writer.field("Summary",review.discrepancies()+" discrepancies | "+review.warnings()+" open notes | "+review.passed()+" fulfilled");writer.line("Automatic pre-check only. Final professional review remains required.");writer.space();int index=1;for(CheckResult item:review.results()){writer.heading(index+++". "+status(item)+" - "+item.message());writer.line("Automatic assessment: "+(item.automaticSeverity()==null?"not available":item.automaticSeverity().name()));writer.line("Rule code: "+value(item.code()));writer.line("Rule: "+item.rule().id()+" | Version: "+item.rule().version()+" | Catalog: "+item.ruleCatalogVersion());writer.line("Rule basis: "+item.rule().basis());writer.line("Rule explanation: "+item.rule().explanation());writer.line("Rule limitations: "+item.rule().limitations());writer.line("LC condition / comparison basis: "+value(item.lcCondition()));writer.line("Document: "+value(item.documentName()));writer.line("Document value / text evidence: "+value(item.documentEvidence()));writer.line("Exact PDF page reference: not recorded");if(item.reviewDecision()!=null){writer.line("Manual decision: "+("ACCEPTED".equals(item.reviewDecision())?"fulfilled":"discrepancy confirmed"));writer.line("Reviewed by: "+value(item.reviewedBy())+" | "+item.reviewedAt());writer.line("Decision reason: "+value(item.reviewComment()));}else{writer.line("Manual decision: pending - no professional decision recorded");}writer.space();}writer.close();pdf.save(out);return new Report("Pruefbericht-"+safe(lc.getReference())+".pdf",out.toByteArray());}}
 private String status(CheckResult r){return switch(r.severity()){case OK->"FULFILLED";case WARNING->"OPEN NOTE";case DISCREPANCY->"DISCREPANCY";};}private String value(String v){return v==null||v.isBlank()?"-":v;}private String safe(String v){return v==null?"LC":v.replaceAll("[^A-Za-z0-9._-]","_");}public record Report(String filename,byte[] content){}
 private static class PageWriter{private final PDDocument pdf;private final PDFont regular,bold;private PDPageContentStream stream;private float y;private int page;
PageWriter(PDDocument p,PDFont r,PDFont b)throws IOException{pdf=p;regular=r;bold=b;newPage();}void newPage()throws IOException{if(stream!=null){footer();stream.close();}PDPage sheet=new PDPage(PDRectangle.A4);pdf.addPage(sheet);stream=new PDPageContentStream(pdf,sheet);y=790;page++;}void title(String s)throws IOException{write(bold,18,s,50);y-=8;}void heading(String s)throws IOException{ensure(55);write(bold,11,s,50);}void field(String l,String v)throws IOException{ensure(20);write(bold,9,l+":",50);y+=14;write(regular,9,v,150);}void line(String s)throws IOException{for(String part:wrap(clean(s),95)){ensure(16);write(regular,9,part,60);}}void space(){y-=6;}void ensure(float h)throws IOException{if(y-h<55)newPage();}void write(PDFont f,float size,String s,float x)throws IOException{stream.beginText();stream.setFont(f,size);stream.newLineAtOffset(x,y);stream.showText(clean(s));stream.endText();y-=14;}void footer()throws IOException{stream.beginText();stream.setFont(regular,8);stream.newLineAtOffset(50,30);stream.showText("Corporate LC Manager | Page "+page);stream.endText();}void close()throws IOException{footer();stream.close();stream=null;}String clean(String s){return (s==null?"-":s).replace('ä','a').replace('ö','o').replace('ü','u').replace('Ä','A').replace('Ö','O').replace('Ü','U').replace("ß","ss").replaceAll("[^\\x20-\\x7E]"," ").replaceAll("\\s+"," ").trim();}List<String> wrap(String s,int max){List<String> out=new ArrayList<>();StringBuilder line=new StringBuilder();for(String word:s.split(" ")){if(line.length()>0&&line.length()+word.length()+1>max){out.add(line.toString());line.setLength(0);}if(line.length()>0)line.append(' ');line.append(word);}if(line.length()>0)out.add(line.toString());return out.isEmpty()?List.of("-"):out;}}
}
